-- HU-15: one row per status change of a request (D-08, docs/modelo-datos.md §3)
CREATE TABLE "status_history" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "request_id" UUID NOT NULL,
    "previous_status" VARCHAR(12),
    "new_status" VARCHAR(12) NOT NULL,
    "user_id" UUID NOT NULL,
    "comment" TEXT,
    "visible_to_requester" BOOLEAN NOT NULL DEFAULT true,
    "changed_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "status_history_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "status_history_request_id_fkey" FOREIGN KEY ("request_id") REFERENCES "requests"("id") ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT "status_history_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE,
    -- Added by hand: Prisma does not generate CHECK constraints.
    -- previous_status is NULL only in the row that records the creation.
    CONSTRAINT "status_history_previous_status_check" CHECK ("previous_status" IS NULL OR "previous_status" IN ('RECIBIDA', 'EN_BUSQUEDA', 'DISPONIBLE', 'AGENDADA', 'ATENDIDA', 'CERRADA', 'RECHAZADA')),
    CONSTRAINT "status_history_new_status_check" CHECK ("new_status" IN ('RECIBIDA', 'EN_BUSQUEDA', 'DISPONIBLE', 'AGENDADA', 'ATENDIDA', 'CERRADA', 'RECHAZADA')),
    CONSTRAINT "status_history_status_changed_check" CHECK ("previous_status" IS DISTINCT FROM "new_status")
);

-- Timeline of a request and attention times (§4)
CREATE INDEX "status_history_request_id_changed_at_idx" ON "status_history"("request_id", "changed_at");
CREATE INDEX "status_history_user_id_idx" ON "status_history"("user_id");

-- Added by hand: the history is the audit trail, so it only admits INSERT (D-08)
CREATE FUNCTION "status_history_reject_changes"() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION 'status_history solo admite INSERT (D-08)';
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER "status_history_insert_only"
    BEFORE UPDATE OR DELETE OR TRUNCATE ON "status_history"
    FOR EACH STATEMENT EXECUTE FUNCTION "status_history_reject_changes"();
